// ============================================
// ARCADIA CALCULATOR BOT v2.0 — COMPLETE
// n8n Code Node
// ============================================

// --- CONFIG ---
const BOT_TOKEN = 'REDACTED_TELEGRAM_BOT_TOKEN';
const SUPABASE_URL = 'https://xfibcjhshpmqkrhlpsoa.supabase.co/rest/v1';
const SUPABASE_KEY = 'eyJ-REDACTED-SERVICE-ROLE';
const EXCHANGE_API = 'https://open.er-api.com/v6/latest/USD';
const DEFAULT_RATES = { RUB: 88, KZT: 500 };
const WA_RUSSIA = '+7 705 118 1845';
const WA_OTHER = '+380936582617';

// --- DESTINATIONS ---
const DESTS = {
  KZ: {
    name_ar: 'كازاخستان 🇰🇿', name_en: 'Kazakhstan', country: 'Kazakhstan', currency: 'KZT', wa: WA_OTHER, hasSIM: true,
    cities: { Almaty: { ar: 'ألماتي', en: 'Almaty' }, 'Almaty Region': { ar: 'منتجع أوي-قاراغاي', en: 'Oi-Qaragai Resort' } },
    routes: [
      { code: 'ALM', label_ar: '🏙 ألماتي فقط', label_en: '🏙 Almaty only', cities: ['Almaty'] },
      { code: 'ALM_RES', label_ar: '🏙+🏔 ألماتي + منتجع', label_en: '🏙+🏔 Almaty + Resort', cities: ['Almaty', 'Almaty Region'] },
      { code: 'ALM_RES_ALM', label_ar: '🔄 ألماتي + منتجع + ألماتي', label_en: '🔄 Almaty + Resort + Almaty', cities: ['Almaty', 'Almaty Region', 'Almaty'] }
    ]
  },
  RU: {
    name_ar: 'روسيا 🇷🇺', name_en: 'Russia', country: 'Russia', currency: 'RUB', wa: WA_RUSSIA, hasSIM: false,
    cities: { Moscow: { ar: 'موسكو', en: 'Moscow' }, 'Saint Petersburg': { ar: 'سان بطرسبرغ', en: 'St. Petersburg' } },
    routes: [
      { code: 'MOW', label_ar: '🏙 موسكو فقط', label_en: '🏙 Moscow only', cities: ['Moscow'] },
      { code: 'SPB', label_ar: '🏙 سان بطرسبرغ فقط', label_en: '🏙 St. Petersburg only', cities: ['Saint Petersburg'] },
      { code: 'MOW_SPB', label_ar: '🏙+🏙 موسكو + سانت', label_en: '🏙+🏙 Moscow + St.Petersburg', cities: ['Moscow', 'Saint Petersburg'] },
      { code: 'MOW_SPB_MOW', label_ar: '🔄 موسكو + سانت + موسكو', label_en: '🔄 Moscow + St.Pete + Moscow', cities: ['Moscow', 'Saint Petersburg', 'Moscow'] }
    ]
  }
};

// --- HELPERS ---
const cAR = c => { for (const d of Object.values(DESTS)) if (d.cities[c]) return d.cities[c].ar; return c; };
const cEN = c => { for (const d of Object.values(DESTS)) if (d.cities[c]) return d.cities[c].en; return c; };
const svcCity = c => c === 'Almaty Region' ? 'Almaty' : c;
const fUSD = v => '$' + Math.round(v).toLocaleString('en-US');
const fSAR = v => Math.round(v * 3.75).toLocaleString('en-US') + ' ر.س';
const occAR = o => o === 'SGL' ? 'مفردة' : o === 'DBL' ? 'مزدوجة' : 'ثلاثية';

function addDays(d, n) { const dt = new Date(d + 'T12:00:00'); dt.setDate(dt.getDate() + n); return dt.toISOString().slice(0, 10); }
function fmtD(d) { if (!d) return ''; const dt = new Date(d + 'T12:00:00'); const m = ['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر']; return dt.getDate() + ' ' + m[dt.getMonth()] + ' ' + dt.getFullYear(); }
function fmtDEN(d) { if (!d) return ''; return new Date(d + 'T12:00:00').toLocaleDateString('en-US', { day: 'numeric', month: 'long', year: 'numeric' }); }

function parseDate(txt) {
  if (!txt) return null; txt = txt.trim();
  let m = txt.match(/^(\d{4})-(\d{2})-(\d{2})$/); if (m) return txt;
  m = txt.match(/^(\d{1,2})[.\/](\d{1,2})(?:[.\/](\d{2,4}))?$/);
  if (m) { const y = m[3] ? (m[3].length === 2 ? '20' + m[3] : m[3]) : '2026'; return `${y}-${String(m[2]).padStart(2,'0')}-${String(m[1]).padStart(2,'0')}`; }
  const MA = {يناير:1,فبراير:2,مارس:3,أبريل:4,ابريل:4,مايو:5,يونيو:6,يوليو:7,أغسطس:8,اغسطس:8,سبتمبر:9,أكتوبر:10,اكتوبر:10,نوفمبر:11,ديسمبر:12};
  for (const [mn,mv] of Object.entries(MA)) { m = txt.match(new RegExp(`(\\d{1,2})\\s*${mn}(?:\\s*(\\d{4}))?`)); if (m) { const y = m[2]||'2026'; return `${y}-${String(mv).padStart(2,'0')}-${String(m[1]).padStart(2,'0')}`; } }
  return null;
}

function parseNumber(txt) { const m = (txt || '').match(/(\d+)/); return m ? parseInt(m[1]) : null; }

function makeRows(btns, cols = 2) { const r = []; for (let i = 0; i < btns.length; i += cols) r.push(btns.slice(i, i + cols)); return r; }

function roomConfigs(adults) {
  const c = [];
  if (adults === 1) c.push({ rooms: [{ occ: 'SGL', count: 1 }], label: 'غرفة مفردة' });
  else if (adults === 2) { c.push({ rooms: [{ occ: 'DBL', count: 1 }], label: 'غرفة مزدوجة' }); c.push({ rooms: [{ occ: 'SGL', count: 2 }], label: '2 مفردة' }); }
  else if (adults === 3) { c.push({ rooms: [{ occ: 'TRP', count: 1 }], label: 'ثلاثية' }); c.push({ rooms: [{ occ: 'DBL', count: 1 }, { occ: 'SGL', count: 1 }], label: 'مزدوجة + مفردة' }); }
  else if (adults === 4) { c.push({ rooms: [{ occ: 'DBL', count: 2 }], label: '2 مزدوجة' }); c.push({ rooms: [{ occ: 'TRP', count: 1 }, { occ: 'SGL', count: 1 }], label: 'ثلاثية + مفردة' }); }
  else if (adults === 5) { c.push({ rooms: [{ occ: 'TRP', count: 1 }, { occ: 'DBL', count: 1 }], label: 'ثلاثية + مزدوجة' }); c.push({ rooms: [{ occ: 'DBL', count: 2 }, { occ: 'SGL', count: 1 }], label: '2 مزدوجة + مفردة' }); }
  else if (adults === 6) { c.push({ rooms: [{ occ: 'TRP', count: 2 }], label: '2 ثلاثية' }); c.push({ rooms: [{ occ: 'DBL', count: 3 }], label: '3 مزدوجة' }); }
  else { const t = Math.floor(adults/3), rem = adults%3, d = Math.floor(rem/2), s = rem%2; const rooms = []; if(t)rooms.push({occ:'TRP',count:t}); if(d)rooms.push({occ:'DBL',count:d}); if(s)rooms.push({occ:'SGL',count:s}); c.push({ rooms, label: rooms.map(r=>`${r.count}×${occAR(r.occ)}`).join('+') }); c.push({ rooms: [{ occ: 'DBL', count: Math.ceil(adults/2) }], label: `${Math.ceil(adults/2)} مزدوجة` }); }
  return c;
}

// --- TELEGRAM ---
async function tg(method, body) { try { return await this.helpers.httpRequest({ url: `https://api.telegram.org/bot${BOT_TOKEN}/${method}`, method: 'POST', body, headers: { 'Content-Type': 'application/json' }, json: true }); } catch(e) { console.log('TG err:', e.message); return null; } }
async function send(chatId, text, kb) { const b = { chat_id: chatId, text, parse_mode: 'HTML' }; if (kb) b.reply_markup = { inline_keyboard: kb }; return tg.call(this, 'sendMessage', b); }
async function aCB(id) { return tg.call(this, 'answerCallbackQuery', { callback_query_id: id }); }

// --- SUPABASE ---
async function sbGet(table, q) { try { return await this.helpers.httpRequest({ url: `${SUPABASE_URL}/${table}${q?'?'+q:''}`, method:'GET', headers:{ apikey:SUPABASE_KEY, Authorization:`Bearer ${SUPABASE_KEY}`, Accept:'application/json' }}); } catch(e){ return []; }}
async function sbPost(table, data) { try { return await this.helpers.httpRequest({ url:`${SUPABASE_URL}/${table}`, method:'POST', body:data, headers:{ apikey:SUPABASE_KEY, Authorization:`Bearer ${SUPABASE_KEY}`, 'Content-Type':'application/json', Prefer:'resolution=merge-duplicates' }, json:true }); } catch(e){ return null; }}

// --- SESSION ---
async function getS(chatId) { const r = await sbGet.call(this,'bot_sessions',`chat_id=eq.${chatId}`); return (r&&r[0]) ? { step:r[0].step||'start', data:r[0].data||{} } : { step:'start', data:{} }; }
async function setS(chatId, step, data) { await sbPost.call(this,'bot_sessions',{ chat_id:chatId, step, data, updated_at:new Date().toISOString() }); }

// --- EXCHANGE RATES ---
async function getRates() { try { const d = await this.helpers.httpRequest({ url:EXCHANGE_API, method:'GET' }); if(d&&d.rates) return { RUB:Math.round(d.rates.RUB)||DEFAULT_RATES.RUB, KZT:Math.round(d.rates.KZT)||DEFAULT_RATES.KZT }; } catch(e){} return {...DEFAULT_RATES}; }
function toUSD(v, cur, r) { return cur==='USD'?v:v/(r[cur]||1); }

// --- DATA ---
async function getHotels(country, city) { let q=`Country=eq.${country}&Status=eq.Active`; if(city)q+=`&City=eq.${city}`; return sbGet.call(this,'hotels',q); }
async function getRooms(hids) { if(!hids.length)return[]; return sbGet.call(this,'room_types',`Hotel_ID=in.(${hids.join(',')})`); }
async function getSeasons(hids, date) { if(!hids.length||!date)return[]; return sbGet.call(this,'seasons',`Hotel_ID=in.(${hids.join(',')})&Start_Date=lte.${date}&End_Date=gte.${date}`); }
async function getRatePlans(hids, sids) { if(!hids.length||!sids.length)return[]; return sbGet.call(this,'rate_plans',`Hotel_ID=in.(${hids.join(',')})&Season_ID=in.(${sids.join(',')})&Status=eq.Active&Meal_Plan=eq.BB`); }
async function getServices(country, city) { return sbGet.call(this,'services',`Country=eq.${country}&City=eq.${svcCity(city)}`); }
async function getItinDays(country, city) { return sbGet.call(this,'itineraries',`country=eq.${country}&city=eq.${city}&order=tour_order`); }

// Smart itinerary builder
async function buildItinerary(S) {
  const { destination, route } = S.data;
  const dest = DESTS[destination];
  const program = [];
  let dayNum = 1;
  const isMultiCity = route.length > 1;
  const uniqueCities = [...new Set(route.map(s => s.city))];

  for (let si = 0; si < route.length; si++) {
    const stop = route[si];
    const { city, nights, tours } = stop;
    const isFirst = si === 0;
    const isLast = si === route.length - 1;
    const cityDays = await getItinDays.call(this, dest.country, city);
    if (!cityDays || !cityDays.length) continue;

    // Arrival day (first city only)
    if (isFirst) {
      const arr = cityDays.find(d => d.type === 'arrival');
      if (arr) program.push({ ...arr, day_number: dayNum++ });
    }

    // Transfer day (arriving from previous city)
    if (!isFirst) {
      // Find transfer from previous city
      const prevCity = route[si - 1].city;
      const prevDays = await getItinDays.call(this, dest.country, prevCity);
      const tf = prevDays ? prevDays.find(d => d.type === 'transfer') : null;
      if (tf) program.push({ ...tf, day_number: dayNum++ });
      else program.push({ day_number: dayNum++, type: 'transfer', title_ar: `تنقل إلى ${cAR(city)}`, title_en: `Transfer to ${cEN(city)}` });
    }

    // Tour days
    const tourDays = cityDays.filter(d => d.type === 'tour').sort((a, b) => (a.tour_order || 0) - (b.tour_order || 0));
    const numTours = tours || 0;
    for (let t = 0; t < numTours && t < tourDays.length; t++) {
      program.push({ ...tourDays[t], day_number: dayNum++ });
    }

    // Free days = nights - tours - (transfer day if not last) - (arrival if first, counted above)
    let usedDays = numTours;
    if (isFirst) usedDays += 1; // arrival
    if (!isFirst) usedDays += 1; // transfer in
    if (isLast) usedDays += 1; // departure (will be added below)

    const freeDays = Math.max(0, nights - usedDays + (isLast ? 1 : 0));
    const freeTemplate = cityDays.find(d => d.type === 'free');
    for (let f = 0; f < freeDays; f++) {
      if (freeTemplate) program.push({ ...freeTemplate, day_number: dayNum++, title_ar: `يوم حر في ${cAR(city)}`, title_en: `Free day in ${cEN(city)}` });
      else program.push({ day_number: dayNum++, type: 'free', title_ar: `يوم حر في ${cAR(city)}`, title_en: `Free day in ${cEN(city)}` });
    }

    // Departure day (last city only)
    if (isLast) {
      const dep = cityDays.find(d => d.type === 'departure');
      if (dep) program.push({ ...dep, day_number: dayNum++ });
    }
  }

  return program;
}

function pickVehicle(svcs, cat, pax) { return svcs.filter(s=>s.Category===cat&&(s.Max_Persons||99)>=pax).sort((a,b)=>a.Price-b.Price)[0]||null; }

function findSeason(seasons, hid, date) {
  const d = new Date(date+'T12:00:00'), day = d.getDay(), isWE = [0,1,5,6].includes(day);
  const m = seasons.filter(s=>s.Hotel_ID===hid);
  const dayType = isWE ? 'Weekend' : 'Weekday';
  const typed = m.filter(s=>s.Season_Name&&s.Season_Name.includes(dayType)).sort((a,b)=>(b.Priority||0)-(a.Priority||0));
  return typed[0] || m.sort((a,b)=>(b.Priority||0)-(a.Priority||0))[0] || null;
}

function occRate(rate, occ) {
  if(!rate) return 0;
  if(occ==='SGL') return parseFloat(rate.SGL_Rate)||0;
  if(occ==='DBL') return parseFloat(rate.DBL_Rate)||0;
  if(occ==='TRP') return parseFloat(rate.TRP_Rate)||0;
  return 0;
}

function calcHotel(hotel, rooms, rates, seasons, cfg, nights, childAges, date, exR) {
  const season = findSeason(seasons, hotel.Hotel_ID, date);
  if (!season || season.Season_Type === 'Blackout' || season.Season_Type === 'Closed' || season.Season_Type === 'Special') return null;
  const hRooms = rooms.filter(r => r.Hotel_ID === hotel.Hotel_ID);
  let total = 0, details = [];
  for (const rc of cfg.rooms) {
    let best = null;
    for (const room of hRooms) {
      // Check Max_Adults capacity
      const maxA = parseInt(room.Max_Adults) || 2;
      if (rc.occ === 'TRP' && maxA < 3) continue;
      if (rc.occ === 'DBL' && maxA < 2) continue;

      const rate = rates.find(r => r.Hotel_ID === hotel.Hotel_ID && r.Room_ID === room.Room_ID && r.Season_ID === season.Season_ID);
      if (!rate) continue;
      const nr = occRate(rate, rc.occ); if (!nr) continue;
      let childEx = 0;
      if (rc.count === 1) for (const age of childAges) { if (age <= 5) childEx += parseFloat(rate.Extra_Child_0_5||0); else if (age <= 11) childEx += parseFloat(rate.Extra_Child_6_11||0); else childEx += parseFloat(rate.Extra_Adult||0); }
      const usd = toUSD((nr + childEx) * nights, hotel.Currency, exR);
      if (!best || usd < best.usd) best = { usd, room, rate, occ: rc.occ };
    }
    if (!best) return null;
    total += best.usd * rc.count;
    details.push({ ...best, count: rc.count });
  }
  return { totalUSD: total, details };
}

// --- PACKAGE BUILDER ---
async function buildPkgs(S) {
  const { destination, route, checkIn, totalNights, adults, children, roomConfig, clientType, withGuide } = S.data;
  const dest = DESTS[destination];
  const markup = clientType === 'B2B' ? 1.15 : 1.20;
  const totalPax = adults + (children||[]).length;
  const exR = await getRates.call(this);

  const uniqCities = [...new Set(route.map(s=>s.city))];
  let allH = [], allSvc = {};
  for (const city of uniqCities) { const h = await getHotels.call(this, dest.country, city); allH = allH.concat(h); allSvc[city] = await getServices.call(this, dest.country, city); }
  const hids = allH.map(h=>h.Hotel_ID);
  const allRm = await getRooms.call(this, hids);
  const allSea = await getSeasons.call(this, hids, checkIn);
  const validSea = allSea.filter(s=>s.Season_Type!=='Blackout'&&s.Season_Type!=='Closed'&&s.Season_Type!=='Special');
  const sids = validSea.map(s=>s.Season_ID);
  const allRP = await getRatePlans.call(this, hids, sids);

  function ranked(city, stars, nights) {
    const hotels = allH.filter(h=>h.City===city&&h.Star_Rating===stars&&h.Status==='Active');
    const res = [];
    for (const h of hotels) { const c = calcHotel(h, allRm, allRP, validSea, roomConfig, nights, children||[], checkIn, exR); if(c) res.push({hotel:h,cost:c}); }
    return res.sort((a,b)=>a.cost.totalUSD-b.cost.totalUSD);
  }

  const tiers = [
    { key:'eco', label:'🥉 الباقة الاقتصادية', en:'Economy', stars:4, pick:'first' },
    { key:'silver', label:'🥈 الباقة الفضية', en:'Silver', stars:4, pick:'median' },
    { key:'gold', label:'🥇 الباقة الذهبية', en:'Gold', stars:5, pick:'first' }
  ];

  const pkgs = [];
  for (const tier of tiers) {
    let stops=[], base=0, curDate=checkIn, ok=true;
    const simDone = new Set();
    for (let si=0; si<route.length; si++) {
      const {city,nights,tours} = route[si];
      const sc = svcCity(city), svcs = allSvc[city]||allSvc[sc]||[];
      const isFirst=si===0, isLast=si===route.length-1;
      const r = ranked(city, tier.stars, nights);
      if (!r.length) { ok=false; break; }
      let chosen;
      if (tier.pick==='first') chosen=r[0];
      else chosen=r[Math.floor(r.length/2)];

      let tfUSD=0;
      if (isFirst||isLast) { const tf=pickVehicle(svcs,'Transfer_Airport',totalPax); if(tf) tfUSD=toUSD(tf.Price,tf.Currency||dest.currency,exR)*(isFirst&&isLast?2:1); }

      let carUSD=0;
      if ((tours||0)>0) { const car=pickVehicle(svcs,'Daily_Rent_8h',totalPax); if(car) carUSD=toUSD(car.Price*(tours||0),car.Currency||dest.currency,exR); }

      let guideUSD=0;
      if (withGuide&&(tours||0)>0) { const g=svcs.find(s=>s.Category==='Guide_Daily'); if(g) guideUSD=toUSD(g.Price*(tours||0),g.Currency||dest.currency,exR); }

      let simUSD=0;
      if (dest.hasSIM&&!simDone.has(sc)) { const sim=svcs.find(s=>s.Category==='SIM_Card'); if(sim){ simUSD=toUSD(sim.Price*adults,sim.Currency||dest.currency,exR); simDone.add(sc); } }

      const stopT = chosen.cost.totalUSD+tfUSD+carUSD+guideUSD+simUSD;
      base += stopT;
      stops.push({ city, nights, date:curDate, hotel:chosen.hotel, cost:chosen.cost, tfUSD, carUSD, guideUSD, simUSD, tours:tours||0, isFirst, isLast });
      curDate = addDays(curDate, nights);
    }
    if (!ok) continue;

    let trainUSD=0;
    const numTransfers = (route.length > 1) ? route.length - 1 : 0;
    if (destination==='RU'&&route.length>1) {
      const tSvc=allSvc['Moscow']||[]; 
      const ts=tSvc.find(s=>s.Category==='Train_Ticket'); 
      const tp=ts?ts.Price:4500; const tc=ts?ts.Currency:'RUB'; 
      trainUSD=toUSD(tp*numTransfers*totalPax,tc,exR); 
      base+=trainUSD;
      // Car for train transfer is already included in tour days count
    }
    // Inter-city car (Kazakhstan) is already included in tour days count

    const final = base*markup;
    pkgs.push({ tier, stops, trainUSD, base, final, markupPct:Math.round((markup-1)*100), exR });
  }
  return pkgs;
}

// --- B2B PROMOTIONAL TABLE ---
async function buildB2BTable(S, extraPerPaxFn) {
  const { destination, route, checkIn, totalNights, tourDays, withGuide } = S.data;
  const dest = DESTS[destination];
  const markup = 1.15;
  const exR = await getRates.call(this);
  const city = route[0].city;
  const nights = totalNights;
  const days = nights + 1;
  const cityTours = S.data._cityTours || tourDays || 0;

  const hotels = await getHotels.call(this, dest.country, city);
  const hids = hotels.map(h=>h.Hotel_ID);
  const allRm = await getRooms.call(this, hids);
  const allSea = await getSeasons.call(this, hids, checkIn);
  const validSea = allSea.filter(s=>s.Season_Type!=='Blackout'&&s.Season_Type!=='Closed'&&s.Season_Type!=='Special');
  const sids = validSea.map(s=>s.Season_ID);
  const allRP = await getRatePlans.call(this, hids, sids);
  const svcs = await getServices.call(this, dest.country, city);

  function cheapestOcc(hotel, occ) {
    const season = findSeason(validSea, hotel.Hotel_ID, checkIn); if(!season) return null;
    const hRooms = allRm.filter(r=>r.Hotel_ID===hotel.Hotel_ID);
    let best = null;
    for (const room of hRooms) {
      const rate = allRP.find(r=>r.Hotel_ID===hotel.Hotel_ID&&r.Room_ID===room.Room_ID&&r.Season_ID===season.Season_ID);
      if(!rate) continue;
      let local = 0;
      if(occ==='SGL') local=parseFloat(rate.SGL_Rate||0);
      else if(occ==='DBL') local=parseFloat(rate.DBL_Rate||0);
      else local=parseFloat(rate.TRP_Rate||0);
      if(!local) continue;
      const usd = toUSD(local, hotel.Currency, exR);
      if(!best||usd<best) best=usd;
    }
    return best;
  }

  function fixedCost(pax) {
    let t = 0;
    // Airport transfer only for single-city B2B (multi-city distributes separately)
    if (!extraPerPaxFn) {
      const tf = pickVehicle(svcs,'Transfer_Airport',pax); if(tf) t+=toUSD(tf.Price,tf.Currency||dest.currency,exR)*2;
    }
    if(cityTours>0){ const car=pickVehicle(svcs,'Daily_Rent_8h',pax); if(car) t+=toUSD(car.Price*cityTours,car.Currency||dest.currency,exR); }
    if(dest.hasSIM) { const sim=svcs.find(s=>s.Category==='SIM_Card'); if(sim) t+=toUSD(sim.Price*pax,sim.Currency||dest.currency,exR); }
    if(withGuide&&cityTours>0){ const g=svcs.find(s=>s.Category==='Guide_Daily'); if(g) t+=toUSD(g.Price*cityTours,g.Currency||dest.currency,exR); }
    // Add shared costs from multi-city
    if (extraPerPaxFn) t += extraPerPaxFn(pax);
    return t;
  }

  function pp(hotelCost, pax) { return Math.round((hotelCost+fixedCost(pax))*markup/pax); }

  const rows = [];
  for (const hotel of hotels) {
    const sgl = cheapestOcc(hotel,'SGL');
    const dbl = cheapestOcc(hotel,'DBL');
    const trp = cheapestOcc(hotel,'TRP');
    if(!dbl&&!sgl) continue;
    const n = nights;
    rows.push({
      name: hotel.Hotel_Name, stars: hotel.Star_Rating,
      SGL: sgl?pp(sgl*n,1):null,
      '2PAX': dbl?pp(dbl*n,2):null,
      '3PAX': trp?pp(trp*n,3):null,
      '4PAX': dbl?pp(2*dbl*n,4):null,
      '6PAX': trp&&dbl?pp(Math.min(2*trp,3*dbl)*n,6):(dbl?pp(3*dbl*n,6):null),
      '8PAX': dbl?pp(4*dbl*n,8):null,
      '10PAX': dbl?pp(5*dbl*n,10):null
    });
  }
  rows.sort((a,b)=>(a['2PAX']||9999)-(b['2PAX']||9999));
  return { rows, days, nights, exR, tourDays, city, destination };
}

function formatB2BMsg(tbl) {
  const dest = DESTS[tbl.destination];
  const f = v => v ? '$'+v : '—';
  let t = `📊 <b>ARCADIA TOURISM — B2B RATES</b>\n`;
  t += `${dest.name_en} — ${cEN(tbl.city)}\n`;
  t += `${tbl.days} Days / ${tbl.nights} Nights | ${tbl.tourDays} Tours\n`;
  t += `━━━━━━━━━━━━━━━\n\n`;
  for (const r of tbl.rows) {
    t += `🏨 <b>${r.name}</b> ${r.stars}⭐\n`;
    t += `SGL:${f(r.SGL)} | 2P:${f(r['2PAX'])} | 3P:${f(r['3PAX'])}\n`;
    t += `4P:${f(r['4PAX'])} | 6P:${f(r['6PAX'])} | 8P:${f(r['8PAX'])} | 10P:${f(r['10PAX'])}\n\n`;
  }
  t += `✅ Includes: Hotel BB, Airport transfers, ${tbl.tourDays} tours`;
  if(dest.hasSIM) t+=', SIM card';
  t += `\n📞 ${dest.wa}`;
  return t;
}

function formatB2BWA(tbl) {
  const dest = DESTS[tbl.destination];
  const f = v => v ? '$'+v : '—';
  let t = `*ARCADIA TOURISM — B2B RATES*\n`;
  t += `${dest.name_en} — ${cEN(tbl.city)}\n`;
  t += `${tbl.days} Days / ${tbl.nights} Nights\n━━━━━━━━━━━━━━━\n\n`;
  for (const r of tbl.rows) {
    t += `🏨 *${r.name}* ${r.stars}⭐\n`;
