async function hB2BGuide(cid, val, S) {
  S.data.withGuide=val==='1';
  await send.call(this,cid,'⏳ جاري بناء الجدول...');

  const uniqueCities = [...new Set(S.data.route.map(s=>s.city))];
  const dest = DESTS[S.data.destination];
  const exR = await getRates.call(this);
  const numCities = uniqueCities.length;

  if(numCities === 1) {
    // Single city
    const tbl=await buildB2BTable.call(this,S);
    if(!tbl||!tbl.rows.length) { await send.call(this,cid,'⚠️ لا توجد أسعار.'); return {step:'b2b_date',data:S.data}; }
    S.data.b2bTable=tbl;
    const msg=formatB2BMsg(tbl);
    const kb=[[{text:'📄 PDF',callback_data:'b2ba:pdf'},{text:'📋 نسخ واتساب',callback_data:'b2ba:wa'}],[{text:'🔄 عرض جديد',callback_data:'b2b:start'},{text:'🏠 القائمة',callback_data:'back:start'}]];
    await send.call(this,cid,msg,kb);
  } else {
    // Multi-city: calculate shared costs per pax
    const firstCity = S.data.route[0].city;
    const firstSvcs = await getServices.call(this, dest.country, firstCity);

    // Shared costs: airport transfer (2x), train tickets, train car transfer
    function sharedCostPerPax(pax) {
      let t = 0;
      // Airport transfers (arrival + departure) — split between cities
      const tf = pickVehicle(firstSvcs,'Transfer_Airport',pax);
      if(tf) t += toUSD(tf.Price, tf.Currency||dest.currency, exR) * 2; // 2 transfers total
      // Train (Russia only)
      if(S.data.destination==='RU') {
        const ts = firstSvcs.find(s=>s.Category==='Train_Ticket');
        const tp = ts ? ts.Price : 4500;
        const tc = ts ? ts.Currency : 'RUB';
        t += toUSD(tp * pax * (numCities-1), tc, exR); // train tickets
        const trainCar = pickVehicle(firstSvcs,'Daily_Rent_8h',pax);
        if(trainCar) t += toUSD(trainCar.Price * (numCities-1), trainCar.Currency||dest.currency, exR); // car to/from station
      }
      // Inter-city car (non-Russia, e.g. Kazakhstan)
      if(S.data.destination!=='RU') {
        const ic = pickVehicle(firstSvcs,'Daily_Rent_8h',pax);
        if(ic) t += toUSD(ic.Price * (numCities-1), ic.Currency||dest.currency, exR);
      }
      // Split shared costs per city (each table adds half)
      return t / numCities;
    }

    // Distribute tours evenly if not specified per city
    const totalTours = S.data.tourDays || 0;
    const toursPerCity = Math.floor(totalTours / numCities);
    const extraTours = totalTours % numCities;

    S.data.b2bTables = [];
    let header = `📊 <b>B2B — ${S.data.route.map(s=>cAR(s.city)).join(' + ')}</b>\n`;
    header += `📅 ${fmtD(S.data.checkIn)} | ${S.data.totalNights} ليالٍ | ${totalTours} جولات\n`;
    header += `━━━━━━━━━━━━━━━\n`;
    header += `💡 <b>اختر فندق من كل جدول — مجموعهم = السعر الإجمالي للشخص</b>\n`;
    await send.call(this,cid,header);

    for (let ci = 0; ci < uniqueCities.length; ci++) {
      const city = uniqueCities[ci];
      const cityNights = S.data.route.filter(s=>s.city===city).reduce((a,s)=>a+s.nights,0);
      const cityTours = toursPerCity + (ci < extraTours ? 1 : 0);
      const cityS = { data: { ...S.data, route: [{ city, nights: cityNights, tours: cityTours }], totalNights: cityNights, _cityTours: cityTours } };
      const tbl = await buildB2BTable.call(this, cityS, sharedCostPerPax);
      if (tbl && tbl.rows.length) {
        tbl.city = city;
        tbl.nights = cityNights;
        tbl.tourDays = cityTours;
        S.data.b2bTables.push(tbl);
        const msg = formatB2BMsg(tbl);
        await send.call(this, cid, msg);
      }
    }
    const kb=[[{text:'📄 PDF',callback_data:'b2ba:pdf'}],[{text:'🔄 عرض جديد',callback_data:'b2b:start'},{text:'🏠 القائمة',callback_data:'back:start'}]];
    await send.call(this,cid,`✅ فندق من الجدول الأول + فندق من الجدول الثاني = <b>السعر الإجمالي للشخص</b>`,kb);
  }
  return {step:'b2b_result',data:S.data};
}

async function hB2BAction(cid, act, S) {
  if(act==='wa') {
    const t=formatB2BWA(S.data.b2bTable);
    await send.call(this,cid,`📋 <b>انسخ:</b>\n\n<code>${t}</code>`);
    return {step:'b2b_result',data:S.data};
  }
  if(act==='pdf') {
    await send.call(this,cid,'⏳ جاري إنشاء PDF...');
    try {
      const tbl = S.data.b2bTable || (S.data.b2bTables && S.data.b2bTables[0]);
      if(!tbl) { await send.call(this,cid,'⚠️ لا توجد بيانات'); return {step:'b2b_result',data:S.data}; }

      // Send PDF for each table (single or multi-city)
      const tables = S.data.b2bTables && S.data.b2bTables.length ? S.data.b2bTables : [S.data.b2bTable];
      for (const t of tables) {
        const dest = DESTS[S.data.destination];
        const pdfData = {
          rows: t.rows, days: t.days, nights: t.nights,
          tourDays: t.tourDays || S.data.tourDays || 0,
          city: t.city, destination: S.data.destination,
          withGuide: S.data.withGuide, season: '2026',
          exRates: t.exRates
        };
        const cityName = cEN(t.city).replace(/\s+/g,'-');
        const result = await this.helpers.httpRequest({
          url: 'http://172.17.0.1:3456/generate-and-send',
          method: 'POST',
          body: { type: 'b2b', data: pdfData, chatId: cid, botToken: BOT_TOKEN,
                  filename: `Arcadia-B2B-${cityName}-${t.days}Days.pdf`,
                  caption: `📊 B2B Rates — ${cEN(t.city)} — ${t.days} Days` },
          headers: { 'Content-Type': 'application/json' },
          json: true
        });
        if(!result||!result.ok) await send.call(this,cid,`⚠️ خطأ PDF: ${result?.error||'unknown'}`);
      }
      await send.call(this,cid,'✅ تم إرسال PDF');
    } catch(e) {
      await send.call(this,cid,`⚠️ خطأ: ${e.message}`);
    }
    return {step:'b2b_result',data:S.data};
  }
  return {step:'b2b_result',data:S.data};
}

// ============================================
// MAIN PROCESSOR
// ============================================
const update = $input.first().json;
const msg = update.message;
const cb = update.callback_query;
const cid = msg?.chat?.id || cb?.message?.chat?.id;
const txt = (msg?.text || '').trim();
const cbd = cb?.data || '';

if (!cid) return [{ json: { error: 'no chat_id' } }];
if (cb?.id) await aCB.call(this, cb.id);

let S = await getS.call(this, cid);
let res = null;

// --- GLOBAL COMMANDS ---
if (txt === '/start' || txt === 'ابدأ' || txt === 'بداية جديدة' || txt === 'من البداية') {
  res = await hStart.call(this, cid);
} else if (txt === '/cancel' || txt === 'إلغاء' || txt === 'الغاء') {
  res = await hStart.call(this, cid);
} else if (txt === '/b2b' || txt === 'عرض شركات' || txt === 'ترويجي' || txt === 'شركات') {
  res = await hB2BStart.call(this, cid);
} else if (txt === '/help' || txt === 'مساعدة') {
  res = await hHelp.call(this, cid);
} else if (txt === 'رجوع' || txt === 'back') {
  // Generic back
  if (S.step === 'result') res = await hAskTours.call(this, cid, S);
  else res = await hStart.call(this, cid);
}

// --- CALLBACK HANDLERS ---
else if (cbd) {
  const [a, v] = cbd.split(':');
  switch(a) {
    case 'dest': res=await hDest.call(this,cid,v,S); break;
    case 'route': res=await hRoute.call(this,cid,v,S); break;
    case 'depart': res=await hDepart.call(this,cid,v,S); break;
    case 'type': res=await hType.call(this,cid,v,S); break;
    case 'nights': res=await hNights.call(this,cid,parseInt(v),S); break;
    case 'cn': res=await hCNights.call(this,cid,parseInt(v),S); break;
    case 'adults': res=await hAdults.call(this,cid,parseInt(v),S); break;
    case 'ch': res=await hChildren.call(this,cid,parseInt(v),S); break;
    case 'cage': res=await hChildAge.call(this,cid,parseInt(v),S); break;
    case 'room': res=await hRooms.call(this,cid,parseInt(v),S); break;
    case 'guide': res=await hGuide.call(this,cid,v,S); break;
    case 'tours': res=await hTours.call(this,cid,parseInt(v),S); break;
    case 'ct': res=await hCTours.call(this,cid,parseInt(v),S); break;
    case 'act': res=await hAction.call(this,cid,v,S); break;
    case 'rc': res=await hRecalc.call(this,cid,v,S); break;
    case 'inv': res=await hInvTier.call(this,cid,parseInt(v),S); break;
    case 'back': if(v==='start') res=await hStart.call(this,cid); else if(v==='type') res=await hAskType.call(this,cid,S); break;
    // B2B callbacks
    case 'b2b': if(v==='start') res=await hB2BStart.call(this,cid); break;
    case 'b2bd': res=await hB2BDest.call(this,cid,v,S); break;
    case 'b2br': res=await hB2BRoute.call(this,cid,v,S); break;
    case 'b2bn': res=await hB2BNights.call(this,cid,parseInt(v),S); break;
    case 'b2bcn': res=await hB2BCNights.call(this,cid,parseInt(v),S); break;
    case 'b2bt': res=await hB2BTours.call(this,cid,parseInt(v),S); break;
    case 'b2bg': res=await hB2BGuide.call(this,cid,v,S); break;
    case 'b2ba': res=await hB2BAction.call(this,cid,v,S); break;
    default: res=await hStart.call(this,cid);
  }
}

// --- TEXT INPUT (manual numbers) ---
else if (txt && !res) {
  const num = parseNumber(txt);
  switch(S.step) {
    case 'checkin': res=await hCheckin.call(this,cid,txt,S); break;
    case 'nights': if(num) res=await hNights.call(this,cid,num,S); else { await send.call(this,cid,'⚠️ اكتب رقم'); res={step:S.step,data:S.data}; } break;
    case 'cnights': if(num) res=await hCNights.call(this,cid,num,S); else { await send.call(this,cid,'⚠️ اكتب رقم'); res={step:S.step,data:S.data}; } break;
    case 'adults': if(num) res=await hAdults.call(this,cid,num,S); else { await send.call(this,cid,'⚠️ اكتب عدد البالغين'); res={step:S.step,data:S.data}; } break;
    case 'tours': if(num!==null) res=await hTours.call(this,cid,num,S); else { await send.call(this,cid,'⚠️ اكتب رقم'); res={step:S.step,data:S.data}; } break;
    case 'ctours': if(num!==null) res=await hCTours.call(this,cid,num,S); else { await send.call(this,cid,'⚠️ اكتب رقم'); res={step:S.step,data:S.data}; } break;
    case 'b2b_date': res=await hB2BDate.call(this,cid,txt,S); break;
    case 'b2b_nights': if(num) res=await hB2BNights.call(this,cid,num,S); break;
    case 'b2b_cnights': if(num) res=await hB2BCNights.call(this,cid,num,S); break;
    case 'b2b_tours': if(num!==null) res=await hB2BTours.call(this,cid,num,S); break;
    case 'pdf_name': res=await hPDFName.call(this,cid,txt,S); break;
    case 'inv_name': res=await hInvName.call(this,cid,txt,S); break;
    case 'inv_company': res=await hInvCompany.call(this,cid,txt,S); break;
    case 'inv_email': res=await hInvEmail.call(this,cid,txt,S); break;
    case 'inv_phone': res=await hInvPhone.call(this,cid,txt,S); break;
    default: res=await hStart.call(this,cid);
  }
}

else if (!res) { res=await hStart.call(this,cid); }

if (res) await setS.call(this, cid, res.step, res.data);
return [{ json: { ok: true, step: res?.step } }];
